var nimFwDbgPayTxCurrent* {.wifiCtrl, exportc: "nimfw_dbg_pay_tx_current".}: uint32
var nimFwDbgPayTxThd* {.wifiCtrl, exportc: "nimfw_dbg_pay_tx_thd".}: uint32
