# Vendor ke_event.o .rodata.ke_evt_hdlr table. The scheduler indexes this table
# with __clz(event_field), so index 0 handles bit 31 and index 25 handles bit 6.
# Nim stores function-pointer aggregate initializers in module init code for this
# target, so populate this explicitly before the first scheduler pass.
var keEvtHandlers* {.wifiCtrlExport.}: array[KE_EVT_MAX, KeEvtEntry]
var wifiFwRuntimeInited* {.wifiCtrl.}: uint8

proc ke_evt_handlers_init*() {.exportc, cdecl.} =
  keEvtHandlers[0] = KeEvtEntry(handler: cast[pointer](bl_reset_evt), param: nil)
  keEvtHandlers[1] = KeEvtEntry(handler: cast[pointer](mm_timer_schedule), param: nil)
  keEvtHandlers[2] = KeEvtEntry(handler: cast[pointer](ke_timer_schedule), param: nil)
  keEvtHandlers[3] = KeEvtEntry(handler: cast[pointer](ipc_emb_msg_evt), param: nil)
  keEvtHandlers[4] = KeEvtEntry(handler: cast[pointer](ke_task_schedule), param: nil)
  keEvtHandlers[5] = KeEvtEntry(handler: cast[pointer](mm_hw_idle_evt), param: nil)
  keEvtHandlers[6] = KeEvtEntry(handler: cast[pointer](mm_tbtt_evt), param: nil)
  keEvtHandlers[7] = KeEvtEntry(handler: cast[pointer](mm_tbtt_evt), param: nil)
  keEvtHandlers[8] = KeEvtEntry(handler: cast[pointer](rxu_swdesc_upload_evt), param: nil)
  keEvtHandlers[9] = KeEvtEntry(handler: cast[pointer](rxl_dma_evt), param: nil)
  keEvtHandlers[10] = KeEvtEntry(handler: cast[pointer](rxu_cntrl_evt), param: nil)
  keEvtHandlers[11] = KeEvtEntry(handler: cast[pointer](rxl_cntrl_evt), param: nil)
  keEvtHandlers[12] = KeEvtEntry(handler: cast[pointer](txl_frame_evt), param: nil)
  keEvtHandlers[13] = KeEvtEntry(handler: cast[pointer](txl_cfm_evt), param: cast[pointer](4'u))
  keEvtHandlers[14] = KeEvtEntry(handler: cast[pointer](txl_cfm_evt), param: cast[pointer](3'u))
  keEvtHandlers[15] = KeEvtEntry(handler: cast[pointer](txl_cfm_evt), param: cast[pointer](2'u))
  keEvtHandlers[16] = KeEvtEntry(handler: cast[pointer](txl_cfm_evt), param: cast[pointer](1'u))
  keEvtHandlers[17] = KeEvtEntry(handler: cast[pointer](txl_cfm_evt), param: nil)
  keEvtHandlers[18] = KeEvtEntry(handler: cast[pointer](ipc_emb_tx_evt), param: cast[pointer](4'u))
  keEvtHandlers[19] = KeEvtEntry(handler: cast[pointer](ipc_emb_tx_evt), param: cast[pointer](3'u))
  keEvtHandlers[20] = KeEvtEntry(handler: cast[pointer](ipc_emb_tx_evt), param: cast[pointer](2'u))
  keEvtHandlers[21] = KeEvtEntry(handler: cast[pointer](ipc_emb_tx_evt), param: cast[pointer](1'u))
  keEvtHandlers[22] = KeEvtEntry(handler: cast[pointer](ipc_emb_tx_evt), param: nil)
  keEvtHandlers[23] = KeEvtEntry(handler: cast[pointer](bl_event_handle), param: cast[pointer](1'u))
  keEvtHandlers[24] = KeEvtEntry(handler: cast[pointer](bl_event_handle), param: nil)
  keEvtHandlers[25] = KeEvtEntry(handler: cast[pointer](bl_fw_statistic_dump), param: nil)

proc wifi_fw_runtime_init*() {.exportc, cdecl.} =
  ## Initialize wifi_fw runtime state once.
  ##
  ## CRITICAL: do NOT call NimMain() here. `_start` jumps directly to
  ## user `main()`, so NimMain has never been called. NimMain itself
  ## ends with `jal main`, so calling it here would recursively re-enter
  ## main → infinite recursion. Instead, call PreMain — it runs all the
  ## Nim global var initializers (which is what populates dispatch
  ## tables like mm_default_handler) and returns. ke_evt_handlers_init
  ## then wires up the per-event handler table.
  if wifiFwRuntimeInited != 0:
    return
  {.emit: """
  extern void PreMain(void);
  PreMain();
  """.}
  ke_evt_handlers_init()
  wifiFwRuntimeInited = 1

# =============================================================================
# Helper: interrupt save/restore (from disassembly: csrrci/csrsi mstatus,8)
# =============================================================================
template irqSave(): uint32 =
  ## Templated so the `csrrci mstatus, 8` emits inline at the call site,
  ## matching blob (which never wraps the CSR op in a call). Previously a
  ## {.inline.} proc — GCC kept a standalone symbol and every caller
  ## picked up an extra `irqRestore__wifi95fw_u1904`-style call that
  ## isn't in the blob.
  block:
    var irqPrev {.gensym.}: uint32
    {.emit: ["asm volatile(\"csrrci %0, mstatus, 8\" : \"=r\"(", irqPrev, ") );"].}
    irqPrev

template irqRestore(prev: uint32) =
  if (prev and 8) != 0:
    {.emit: ["asm volatile(\"csrsi mstatus, 8\");"].}

proc macTimeNow(): uint32 {.inline.} =
  ## Read current MAC HW timestamp.
  regRead(MACHW_TIMLO_REG)

proc platformDelay(us: uint32) {.inline.} =
  ## Simple busy-wait delay (approximate microseconds).
  ## From blob: wifi_main calls delay(100) during INTC clock toggle.
  var cnt = us * 10'u32  # approximate loop count for ~1us per 10 iterations
  while cnt > 0:
    {.emit: ["asm volatile(\"nop\");"].}
    dec cnt

# =============================================================================
# RC helper: typed access to rc_sta_stats fields from raw byte pointer
# =============================================================================
template rcU8(base: pointer, off: int): var uint8 =
  cast[ptr uint8](cast[uint](base) + off.uint)[]

template rcU16(base: pointer, off: int): var uint16 =
  cast[ptr uint16](cast[uint](base) + off.uint)[]

template rcU32(base: pointer, off: int): var uint32 =
  cast[ptr uint32](cast[uint](base) + off.uint)[]

template rcPtr(base: pointer, off: int): var pointer =
  cast[ptr pointer](cast[uint](base) + off.uint)[]

template rcPrngNext(): uint32 =
  ## Advance the LCG PRNG and return new state. Templated (not a {.inline.}
  ## proc) to force Nim-level inlining so the call graph matches blob,
  ## which emits the LCG arithmetic inline at every use site.
  rcPrngState = rcPrngState * RC_PRNG_MULT + RC_PRNG_INCR
  rcPrngState

proc rcRateEntryPtr(stats: pointer, idx: int): pointer {.inline.} =
  ## Get pointer to rate entry i within rc_sta_stats.
  ## Rate entries start at offset 0, each 12 bytes.
  cast[pointer](cast[uint](stats) + (idx * RC_RATE_ENTRY_SIZE).uint)

template rcRateEntryAt(p: pointer): ptr RcRateEntryView =
  cast[ptr RcRateEntryView](p)

template rcRateEntry(stats: pointer, idx: uint16): ptr RcRateEntryView =
  cast[ptr RcRateEntryView](cast[uint](stats) + idx.uint * RC_RATE_ENTRY_SIZE.uint)

template rcRateResetFields(stats: pointer, idx: uint16): ptr RcRateResetFieldsView =
  cast[ptr RcRateResetFieldsView](cast[uint](stats) + idx.uint * RC_RATE_ENTRY_SIZE.uint)

template rcThroughputArray(tpArray: pointer): ptr UncheckedArray[uint32] =
  cast[ptr UncheckedArray[uint32]](tpArray)

template rcStatsCounters(stats: pointer): ptr RcStatsCounterView =
  cast[ptr RcStatsCounterView](stats)

proc rcClearRateEntryTransientStats(stats: pointer; idx: uint16) {.inline.} =
  let entry = rcRateResetFields(stats, idx)
  entry.sampleSkipped = 0
  entry.initialized = 1
  entry.attempts0 = 0
  entry.oldProb = 0

proc rcRateConfig(stats: pointer, idx: int): uint16 {.inline.} =
  ## Read rate_config from entry i (at entry base + 10).
  rcU16(stats, idx * RC_RATE_ENTRY_SIZE + 10)

proc rcSetRateConfig(stats: pointer, idx: int, val: uint16) {.inline.} =
  ## Write rate_config to entry i.
  rcU16(stats, idx * RC_RATE_ENTRY_SIZE + 10) = val

const RcRandomRateAttemptLimit = 64

proc rc_pick_non_duplicate_rate(stats: pointer): uint16 =
  ## Pick a non-duplicate sample rate with a deterministic fallback.
  ## rc_new_random_rate can keep returning existing entries, so production
  ## firmware must not rely on RNG convergence for scheduler progress.
  var randomRate: uint16 = 0xFFFF'u16
  var tries = 0
  while tries < RcRandomRateAttemptLimit:
    randomRate = rc_new_random_rate(stats)
    if rc_check_rate_duplicated(stats, randomRate) == 0:
      return randomRate
    inc tries

  let fmtForFill = rcU8(stats, RCS_FORMAT_MOD)
  if fmtForFill <= 1:
    let rateMap = rcU16(stats, RCS_RATE_MAP)
    let lo = rcU8(stats, RCS_LOWEST_IDX)
    let hi = rcU8(stats, RCS_HIGHEST_IDX)
    let bw = rcU8(stats, RCS_BW_MAX).uint16 shl 10
    var idx = lo
    while idx <= hi:
      if ((rateMap shr idx) and 1'u16) != 0:
        var candidate = (fmtForFill.uint16 shl 11) or idx.uint16
        if idx == 0:
          candidate = candidate or 0x400'u16
        elif idx - 1 <= 2:
          candidate = candidate or bw
        if rc_check_rate_duplicated(stats, candidate) == 0:
          return candidate
      if idx == 0xFF'u8:
        break
      inc idx
  else:
    let groupCnt = rcU8(stats, RCS_GROUP_CNT)
    let maxMcs = rcU8(stats, RCS_MAX_NSS_MCS)
    let sgi = rcU8(stats, RCS_SHORT_GI)
    var group: uint8 = 0
    while group <= groupCnt:
      let bitmap = rcU8(stats, RCS_RATE_BITMAP + group.int)
      var mcs: uint8 = 0
      while mcs <= maxMcs and mcs < 8:
        if ((bitmap shr mcs) and 1'u8) != 0:
          var candidate = (fmtForFill.uint16 shl 11) or
                          (group.uint16 shl 3) or mcs.uint16
          if sgi != 0:
            candidate = candidate or 0x200'u16
          if rc_check_rate_duplicated(stats, candidate) == 0:
            return candidate
        inc mcs
      if group == 0xFF'u8:
        break
      inc group
  0xFFFF'u16

proc rcRateEntryTp(stats: pointer, idx: int): uint16 {.inline.} =
  ## Read throughput estimate from entry i (at entry base + 8).
  rcU16(stats, idx * RC_RATE_ENTRY_SIZE + 8)

proc rcRateEntryProb(stats: pointer, idx: int): uint16 {.inline.} =
  ## Read probability EWMA from entry i (at entry base + 4).
  rcU16(stats, idx * RC_RATE_ENTRY_SIZE + 4)

proc rcRateTp(stats: pointer, idx: int): uint16 {.inline.} =
  ## Read throughput value from entry i (at entry base + 8).
  rcU16(stats, idx * RC_RATE_ENTRY_SIZE + 8)

proc rcRateEntryRetry(stats: pointer, idx: int): uint8 {.inline.} =
  ## Read retry count from entry i (at entry base + 12).
  rcU8(stats, idx * RC_RATE_ENTRY_SIZE + 12)

proc rcRateEntryFlags(stats: pointer, idx: int): uint8 {.inline.} =
  ## Read flags byte from entry i (at entry base + 13).
  rcU8(stats, idx * RC_RATE_ENTRY_SIZE + 13)

proc rcCountBitsInMap(rateMap: uint16, fromBit: int, toBit: int): uint16 =
  ## Count set bits in rateMap from fromBit to toBit (inclusive).
  var count: uint16 = 0
  for i in fromBit .. toBit:
    if (rateMap and (1'u16 shl i)) != 0:
      inc count
  return count

proc rcHighestBit(val: uint8): uint8 =
  ## Find index of highest set bit in a byte (0-7). Returns 0 if val==0.
  var idx: uint8 = 0
  var v = val
  while v > 1:
    v = v shr 1
    inc idx
  return idx

# ###########################################################################
#                      COMMON UTILITIES
# ###########################################################################

proc ascii_to_hex*(c: uint8): uint8 {.exportc, cdecl.} =
  ## Convert a single ASCII hex character to its 4-bit value.
  ## '0'-'9' -> 0-9, 'a'-'f' -> 10-15, 'A'-'F' -> 10-15, else 0.
  let v = c - ord('0').uint8
  if v <= 9: return v
  let lower = c - ord('a').uint8
  if lower <= 5: return c - 87  # 'a' - 87 = 10
  let upper = c - ord('A').uint8
  if upper <= 5: return c - 55  # 'A' - 55 = 10
  return 0

